import h5py, numpy as np
def wq(x, w, q):
    i = np.argsort(x); c = np.cumsum(w[i]); c /= c[-1]
    return np.interp(q, c, x[i])
p="results/quiescent-test-set-speedups-2026-10-01/run/fits/fit/210210-M1_210210/ceridwen_result.h5"
f=h5py.File(p); s=f["samples"]
w=np.exp(s["log_weights"][:]-s["log_weights"][:].max()); w/=w.sum()
print("ess", 1/np.sum(w**2))
b={"diffuse_tau_noll":(0,1),"diffuse_delta":(-1,0.4),"diffuse_Ebump":(0,6),"dust_ratio":(0,2),"zh_beta_unit":(0,1),"log_f_calib":(np.log(.01),np.log(.1))}
for k in s:
    if k in("log_weights","log_likelihoods","log_likelihoods_birth","logsfr_ratios"): continue
    x=s[k][:]; q=wq(x,w,[.16,.5,.84])
    line=f"{k:18s} {q[0]:8.3f} {q[1]:8.3f} {q[2]:8.3f} min {x.min():8.3f} max {x.max():8.3f}"
    if k in b:
        lo,hi=b[k]; r=hi-lo
        line+=f"  frac<5%edge lo {w[x<lo+.05*r].sum():.3f} hi {w[x>hi-.05*r].sum():.3f}"
    print(line)
EOF",
